    GradientDrawable bg(int a,int b,float r){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(r));return g;}
    GradientDrawable stroke(int fill,int line,float r){GradientDrawable g=bg(fill,fill,r);g.setStroke(dp(1),line);return g;}
