    void browserPage(){body.addView(label("BROWSER PREVIEW"));LinearLayout c=card();TextView t=text("SALAM WEB SERVER",11,CYAN);t.setGravity(Gravity.CENTER);c.addView(t);TextView n=text("Local Server Control Panel",24,WHITE);n.setTypeface(null,1);n.setGravity(Gravity.CENTER);c.addView(n,new LinearLayout.LayoutParams(-1,dp(45)));TextView st=text(WebServerService.running?"● ONLINE":"● OFFLINE",11,WebServerService.running?GREEN:RED);st.setGravity(Gravity.CENTER);c.addView(st);body.addView(c);rowTile(R.drawable.ic_folder,"View Files","Open the hosted web root",()->openBrowser());rowTile(R.drawable.ic_dashboard,"Server Info","IP • port • requests • clients",()->show(NETWORK));rowTile(R.drawable.ic_log,"Live Logs","Request history",()->show(LOGS));rowTile(R.drawable.ic_settings,"Server Settings","Manage server configuration",()->show(SETTINGS));}

    void qr(){if(!WebServerService.running){toast("Start the server first");return;}try{String u=WebServerService.currentUrl(this);BitMatrix m=new QRCodeWriter().encode(u,BarcodeFormat.QR_CODE,720,720);Bitmap b=Bitmap.createBitmap(720,720,Bitmap.Config.RGB_565);for(int x=0;x<720;x++)for(int y=0;y<720;y++)b.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);ImageView iv=new ImageView(this);iv.setImageBitmap(b);iv.setPadding(dp(16),dp(16),dp(16),dp(16));new AlertDialog.Builder(this).setTitle("QR Server Sharing").setMessage(u).setView(iv).setPositiveButton("Share URL",(d,w)->share(u)).setNegativeButton("Close",null).show();}catch(Exception e){toast(e.getMessage());}}
    void themeDialog(){String[] x={"Electric Blue","Cyan Night","Purple Neon","Emerald","Amber","Ocean"};new AlertDialog.Builder(this).setTitle("Choose Theme").setSingleChoiceItems(x,pref.getInt("theme",0),(d,w)->{pref.edit().putInt("theme",w).apply();d.dismiss();appShell();toast("Theme changed");}).show();}

    void server(boolean start){try{Intent i=new Intent(this,WebServerService.class);i.setAction(start?"START":"STOP");if(start&&Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception e){toast(e.getMessage());}}
    void copyUrl(){copyText(WebServerService.currentUrl(this));}void copyText(String s){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Salam Web Server",s));toast("Copied to clipboard");}
