    void menuDialog(){String[] x={"Home","Web Files","Network Info","Server Logs","Server Settings","About","Browser Control Panel"};int[] y={HOME,FILES,NETWORK,LOGS,SETTINGS,ABOUT,BROWSER};new AlertDialog.Builder(this).setTitle("Salam Web Server").setItems(x,(d,w)->show(y[w])).show();}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}

    String storageText(){StatFs s=new StatFs(getFilesDir().getAbsolutePath());long total=s.getTotalBytes(),free=s.getAvailableBytes();return format(total-free)+" / "+format(total);}
    String cpuUsage(){try{BufferedReader r=new BufferedReader(new FileReader("/proc/stat"));String line=r.readLine();r.close();if(line==null||!line.startsWith("cpu "))return "—";String[] a=line.trim().split("\\s+");long user=Long.parseLong(a[1]),nice=Long.parseLong(a[2]),sys=Long.parseLong(a[3]),idle=Long.parseLong(a[4]);long total=user+nice+sys+idle;long busy=total-idle;Long ot=pref.getLong("cpuTotal",-1),ob=pref.getLong("cpuBusy",-1);pref.edit().putLong("cpuTotal",total).putLong("cpuBusy",busy).apply();if(ot>0&&total>ot)return String.format(Locale.US,"%.0f%%",100.0*(busy-ob)/(double)(total-ot));return "0%";}catch(Exception e){return "—";}}

    class StatusLights extends View{Paint p=new Paint(1);ValueAnimator pulse;StatusLights(Context c){super(c);pulse=ValueAnimator.ofFloat(.65f,1f,.65f);pulse.setDuration(1100);pulse.setRepeatCount(ValueAnimator.INFINITE);pulse.addUpdateListener(v->invalidate());pulse.start();}protected void onDraw(Canvas c){int w=getWidth(),h=getHeight();for(int i=0;i<7;i++){float x=dp(9+i*17),y=h/2f;int col=WebServerService.running?STATUS_COLORS[i]:RED;float r=dp(5);p.setColor(col);p.setShadowLayer(WebServerService.running?dp(8)*((Float)pulse.getAnimatedValue()):0,0,0,col);setLayerType(View.LAYER_TYPE_SOFTWARE,p);c.drawCircle(x,y,r,p);if(WebServerService.running&&i<6){p.setColor(Color.argb(90,255,255,255));c.drawCircle(x-dp(1),y-dp(1),dp(1.5f),p);}}}}
    static class Wave extends View{Paint p=new Paint(1);Path path=new Path();Wave(Context c){super(c);}protected void onDraw(Canvas c){int w=getWidth(),h=getHeight();int theme=getContext().getSharedPreferences("server",Context.MODE_PRIVATE).getInt("theme",0);int a=BG,b=SURFACE,line=BLUE;if(theme==1){b=Color.rgb(4,50,70);line=CYAN;}else if(theme==2){a=Color.rgb(12,5,28);b=Color.rgb(50,12,85);line=Color.rgb(190,80,255);}else if(theme==3){a=Color.rgb(2,21,18);b=Color.rgb(5,62,48);line=GREEN;}else if(theme==4){a=Color.rgb(30,10,4);b=Color.rgb(75,28,8);line=Color.rgb(255,145,30);}else if(theme==5){a=Color.rgb(3,8,28);b=Color.rgb(13,39,82);line=Color.rgb(72,135,255);}p.setShader(new LinearGradient(0,0,w,h,a,b,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.3f));p.setColor(line);for(int j=0;j<4;j++){path.reset();for(int x=0;x<=w;x+=10){float y=h*.73f+j*dp(16)+(float)Math.sin(x*.013+j)*dp(18);if(x==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);}p.setStyle(Paint.Style.FILL);}}
